        width: 4,
        height: 4,
        coverage: new Uint8ClampedArray([0, 0, 0, 0, 0, 255, 255, 0, 0, 255, 255, 0, 0, 0, 0, 0]),
      }),
      channels: [
        createAlphaChannel({
          id: 'alpha',
          name: 'Alpha',
