          rasterMask: createRasterMask(4, 4, new Uint8ClampedArray(16).fill(192)),
          vectorMask: createVectorMask(4, 4, [
            { type: 'move', x: 0, y: 0 },
            { type: 'line', x: 2, y: 0 },
            { type: 'line', x: 2, y: 4 },
            { type: 'close' },
          ]),
          children: [
            createPixelLayer({
              id: 'pixel',
              name: 'Pixel',
              width: 2,
              height: 2,
