        previous.every((edge, index) => {
          const next = edges.at(index);
          return (
            next !== undefined &&
            edge.axis === next.axis &&
            edge.position === next.position &&
            edge.source === next.source
          );
        })
      ) {
        return previous;
      }
      return edges;
    });
  }, []);
