    const margin = 72;
    const zoom = clampZoom(
      Math.min(
        (stage.clientWidth - margin) / target.canvas.width,
        (stage.clientHeight - margin) / target.canvas.height,
      ),
    );
    setViewport({
      zoom,
      panX: (stage.clientWidth - target.canvas.width * zoom) / 2,
