  useEffect(() => {
    const recentId = localStorage.getItem(RECENT_DOCUMENT_KEY);
    if (!recentId) return;
    let active = true;
    void repository
      .prepareLoad(recentId)
      .then(async (prepared) => {
        if (!active || !prepared) return undefined;
