    setSmartObjectEditSession(null);
    setDocument(parent);
    setSelectedLayerId(smartObjectEditSession.layerId);
    setSelectedLayerIds([smartObjectEditSession.layerId]);
    setViewport(smartObjectEditSession.parentViewport);
