  const closeSizeDialog = useCallback(() => {
    const trigger = sizeDialogTriggerRef.current;
    setSizeDialog(null);
    setActivePixelOperation(null);
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        window.setTimeout(() => {
