describe('cloneStampStroke', () => {
  const sourcePixels = new Uint8ClampedArray([
    255, 0, 0, 255, 0, 255, 0, 255,
    0, 0, 255, 255, 255, 255, 0, 255,
  ]);
  const sourceStore = TiledPixelStore.empty(4, 4)
    .write({ x: 0, y: 0, width: 4, height: 4, pixels: sourcePixels })
    .store;

  const baseOptions: CloneStampOptions = {
    size: 3,
    hardness: 1,
    opacity: 1,
    mode: 'source-over',
  };

  it('copies source pixels to the destination at the correct offset', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray(4 * 4 * 4).fill(0),
    });
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 0, y: 0 },
      true,
      [{ x: 0, y: 0 }],
      baseOptions,
    );
    expect(patch.width).toBeGreaterThan(0);
    expect(patch.height).toBeGreaterThan(0);
    // Should have painted the red pixel from source (0,0).
    const redCount = Array.from(patch.pixels).filter((v, i) => i % 4 === 0 && v === 255).length;
    expect(redCount).toBeGreaterThan(0);
  });

  it('preserves the source-to-destination offset in aligned mode', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 8,
      height: 8,
      pixels: new Uint8ClampedArray(8 * 8 * 4).fill(0),
    });
    // Source origin at (1,1), painting at (4,4) should sample source at (4,4).
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 1, y: 1 },
      true,
      [{ x: 4, y: 4 }],
      baseOptions,
    );
    // The source only has data in the 0..3 range; sampling at (4,4) clamps to (3,3).
    // But with the offset, (4,4) - (1,1) = (3,3) in source coords.
    const result = dest.pixelStore.read({ x: 4, y: 4, width: 1, height: 1 });
    expect(result[3]).toBe(255); // alpha should be non-zero if any paint occurred
  });

  it('restarts sampling from source origin in unaligned mode across segments', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 8,
      height: 8,
      pixels: new Uint8ClampedArray(8 * 8 * 4).fill(0),
    });
    // Unaligned: first dab at (2,2) samples source at (0,0)=red.
    // Second dab at (5,5) should also sample source at (0,0)=red (restart).
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 0, y: 0 },
      false,
      [{ x: 2, y: 2 }, { x: 5, y: 5 }],
      baseOptions,
    );
    // Both points should receive red from source origin.
    const p1 = dest.pixelStore.read({ x: 2, y: 2, width: 1, height: 1 });
    const p2 = dest.pixelStore.read({ x: 5, y: 5, width: 1, height: 1 });
    expect(p1[0]).toBe(255); // red at first point
    expect(p2[0]).toBe(255); // red at second point (unaligned restart)
  });

  it('clips to the active selection', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 8,
      height: 8,
      pixels: new Uint8ClampedArray(8 * 8 * 4).fill(0),
    });
    const selection = createRectangularSelection(
      { width: 8, height: 8 },
      { x: 2, y: 2, width: 2, height: 2 },
    );
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 0, y: 0 },
      true,
      [{ x: 0, y: 0 }, { x: 7, y: 7 }],
      baseOptions,
      selection,
    );
    // Only pixels within the selection [2,2..4,4] should be painted.
    expect(dest.pixelStore.read({ x: 0, y: 0, width: 1, height: 1 })[3]).toBe(0); // outside selection
    expect(dest.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 })[3]).toBeGreaterThan(0); // inside
  });

  it('handles missing source state by writing zeros (no crash)', () => {
    const emptySource = TiledPixelStore.empty(4, 4);
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray([100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255]),
    });
    const before = new Uint8ClampedArray(dest.pixelStore.toContiguous());
    // Painting without source should not corrupt existing pixels.
    const patch = cloneStampStroke(
      dest,
      emptySource,
      { x: 0, y: 0 },
      true,
      [{ x: 0, y: 0 }],
      { ...baseOptions, mode: 'source-over' },
    );
    // Result should be all zeros (transparent) since source is empty.
    expect(dest.pixelStore.read({ x: 0, y: 0, width: 1, height: 1 })[3]).toBe(0);
    // But other pixels should remain unchanged.
    expect(dest.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 })).toEqual(before.subarray(12 * 4, 16 * 4));
  });

  it('works with transformed destination layers', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray(4 * 4 * 4).fill(0),
      transform: { a: 2, b: 0, c: 0, d: 2, e: 0, f: 0 },
    });
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 0, y: 0 },
      true,
      [{ x: 2, y: 2 }],
      baseOptions,
    );
    // At document (2,2), layer-local is (1,1). Source at (0,0) = red.
    const localPixel = dest.pixelStore.read({ x: 1, y: 1, width: 1, height: 1 });
    expect(localPixel[0]).toBe(255); // red
  });

  it('supports erase mode', () => {
    const dest = createPixelLayer({
      id: 'dest',
      name: 'Dest',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray([255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255]),
    });
    const patch = cloneStampStroke(
      dest,
      sourceStore,
      { x: 0, y: 0 },
      true,
      [{ x: 0, y: 0 }],
      { ...baseOptions, mode: 'erase', opacity: 0.5 },
    );
    const result = dest.pixelStore.read({ x: 0, y: 0, width: 1, height: 1 });
