+
+/**
+ * Paints a clone stamp stroke by sampling pixels from a source pixel store and
+ * writing them into a destination pixel layer. The source origin is in document
+ * space; aligned mode preserves the source-to-destination offset throughout the
+ * gesture, while unaligned mode resets the source origin for each new stroke
+ * segment.
+ */
+export function cloneStampStroke(
+  destinationLayer: PixelLayer,
+  sourcePixelStore: TiledPixelStore,
+  /** Document-space source origin established by Alt/Option-click. */
+  sourceOrigin: { readonly x: number; readonly y: number },
+  /** True to keep the source offset constant across stroke segments. */
+  aligned: boolean,
+  points: readonly BrushPoint[],
+  options: CloneStampOptions,
+  selection?: SelectionMask | null,
+  /** World transform for the destination layer. Defaults to layer.transform. */
+  worldTransform: LayerTransform = destinationLayer.transform,
+): PixelPatch {
+  validateLayer(destinationLayer);
+  validateTransform(worldTransform);
+  validateSelection(selection);
+  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
+  assertFinite(options.size, 'Clone stamp size');
+  if (options.size <= 0) throw new RangeError('Clone stamp size must be greater than 0');
+  assertUnit(options.hardness, 'Clone stamp hardness');
+  assertUnit(options.opacity, 'Clone stamp opacity');
+  const mode: unknown = options.mode;
+  if (mode !== 'source-over' && mode !== 'erase') {
+    throw new RangeError('Clone stamp mode must be source-over or erase');
+  }
+  for (const [index, point] of points.entries()) {
+    assertFinite(point.x, `Clone stamp point ${String(index)} x`);
+    assertFinite(point.y, `Clone stamp point ${String(index)} y`);
+    assertUnit(point.pressure ?? 1, `Clone stamp point ${String(index)} pressure`);
+  }
+
+  const radius = options.size / 2;
+  const inverse = invertTransform(worldTransform);
+  const spacing = Math.max(0.25, radius * 0.5);
+
+  // Build dab list with interpolation.
+  const dabs: Array<{ x: number; y: number; pressure: number }> = [];
+  const first = points[0];
+  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });
+  for (let index = 1; index < points.length; index += 1) {
+    const start = points[index - 1];
+    const end = points[index];
+    const distance = Math.hypot(end.x - start.x, end.y - start.y);
+    const steps = Math.max(1, Math.ceil(distance / spacing));
+    for (let step = 1; step <= steps; step += 1) {
+      const progress = step / steps;
+      dabs.push({
+        x: start.x + (end.x - start.x) * progress,
+        y: start.y + (end.y - start.y) * progress,
+        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
+      });
+    }
+  }
+
+  // Compute the base source offset in document space.
+  const baseSourceOffsetX = sourceOrigin.x - dabs[0].x;
+  const baseSourceOffsetY = sourceOrigin.y - dabs[0].y;
+
+  // Stroke working set: union of destination dab bounds in layer-local space.
+  let strokeBounds: Bounds | null = null;
+  for (const dab of dabs) {
+    strokeBounds = unionBounds(
+      strokeBounds,
+      localDabBounds(worldTransform, inverse, dab.x, dab.y, radius, destinationLayer.width, destinationLayer.height),
+    );
+  }
+  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
+    return emptyPatch();
+  }
+  const regionLeft = strokeBounds.left;
+  const regionTop = strokeBounds.top;
+  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
+  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
+  const next = destinationLayer.pixelStore.read({
+    x: regionLeft,
+    y: regionTop,
+    width: regionWidth,
+    height: regionHeight,
+  });
+  const selectionRegion = readSelectionRegion(selection, dabs, radius);
+  let changedBounds: Bounds | null = null;
+
+  // Source working set: collect bounds of all source samples in source-local space.
+  let sourceBounds: Bounds | null = null;
+  for (const dab of dabs) {
+    const sourceDocX = dab.x + baseSourceOffsetX;
+    const sourceDocY = dab.y + baseSourceOffsetY;
+    const sourceExtent = radius * 1.5;
+    sourceBounds = unionBounds(
+      sourceBounds,
+      {
+        left: Math.floor(sourceDocX - sourceExtent),
+        top: Math.floor(sourceDocY - sourceExtent),
+        right: Math.ceil(sourceDocX + sourceExtent),
+        bottom: Math.ceil(sourceDocY + sourceExtent),
+      },
+    );
+  }
+
+  // Read the source region in one pass.
+  let sourceRegion: Uint8ClampedArray | null = null;
+  let sourceRegionLeft = 0;
+  let sourceRegionTop = 0;
+  if (sourceBounds !== null && sourceBounds.right >= sourceBounds.left) {
+    const clampedLeft = Math.max(0, sourceBounds.left);
+    const clampedTop = Math.max(0, sourceBounds.top);
+    const clampedRight = Math.min(sourcePixelStore.width - 1, sourceBounds.right);
+    const clampedBottom = Math.min(sourcePixelStore.height - 1, sourceBounds.bottom);
+    if (clampedRight >= clampedLeft && clampedBottom >= clampedTop) {
+      sourceRegion = sourcePixelStore.read({
+        x: clampedLeft,
+        y: clampedTop,
+        width: clampedRight - clampedLeft + 1,
+        height: clampedBottom - clampedTop + 1,
+      });
+      sourceRegionLeft = clampedLeft;
+      sourceRegionTop = clampedTop;
+    }
+  }
+
+  for (const dab of dabs) {
+    // Effective offset (aligned preserves; unaligned uses sourceOrigin directly).
+    const effectiveOffsetX = aligned ? baseSourceOffsetX : sourceOrigin.x - dabs[0].x;
+    const effectiveOffsetY = aligned ? baseSourceOffsetY : sourceOrigin.y - dabs[0].y;
+
+    // Destination dab center in layer-local space.
+    const destLocalCenter = transformPoint(inverse, dab.x, dab.y);
+    const dabRadius = radius * (dab.pressure ?? 1);
+
+    // Source document coordinate.
+    const sourceDocX = dab.x + effectiveOffsetX;
+    const sourceDocY = dab.y + effectiveOffsetY;
+
+    const bounds = localDabBounds(
+      worldTransform,
+      inverse,
+      dab.x,
+      dab.y,
+      radius,
+      destinationLayer.width,
+      destinationLayer.height,
+    );
+    const { left, top, right, bottom } = bounds;
+    for (let y = top; y <= bottom; y += 1) {
+      for (let x = left; x <= right; x += 1) {
+        const documentPoint = transformPoint(worldTransform, x, y);
+        const falloff = dabCoverage(
+          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
+          radius,
+          options.hardness,
+        );
+        const selected = selectionCoverage(
+          selection,
+          documentPoint.x,
+          documentPoint.y,
+          selectionRegion.buffer,
+          selectionRegion.region,
+        );
+        const coverage = falloff * options.opacity * dab.pressure * selected;
+        if (coverage <= 0) continue;
+
+        // Nearest-neighbor sample from source at the corresponding local coordinate.
+        const sampleX = Math.round(sourceDocX + (x - dab.x));
+        const sampleY = Math.round(sourceDocY + (y - dab.y));
+        const srcX = Math.max(0, Math.min(sourcePixelStore.width - 1, sampleX));
+        const srcY = Math.max(0, Math.min(sourcePixelStore.height - 1, sampleY));
+        let r = 0, g = 0, b = 0, a = 0;
+        if (sourceRegion !== null) {
+          const relX = srcX - sourceRegionLeft;
+          const relY = srcY - sourceRegionTop;
+          const sourceWidth = sourceRegion.length / 4;
+          const offset = (relY * sourceWidth + relX) * 4;
+          r = sourceRegion[offset] ?? 0;
+          g = sourceRegion[offset + 1] ?? 0;
+          b = sourceRegion[offset + 2] ?? 0;
+          a = sourceRegion[offset + 3] ?? 0;
+        }
+
+        const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
+        const before = [next[offset], next[offset + 1], next[offset + 2], next[offset + 3]];
+        if (options.mode === 'erase') {
+          next[offset + 3] = Math.round((next[offset + 3] ?? 0) * (1 - coverage));
+        } else {
+          const sourceAlpha = a / 255;
+          const destinationAlpha = (next[offset + 3] ?? 0) / 255;
+          const outputAlpha = sourceAlpha * coverage + destinationAlpha * (1 - sourceAlpha * coverage);
+          if (outputAlpha > 0) {
+            for (let channel = 0; channel < 3; channel += 1) {
+              const src = channel === 0 ? r : channel === 1 ? g : b;
+              const dst = next[offset + channel] ?? 0;
+              next[offset + channel] = Math.round(
+                (src * sourceAlpha * coverage + dst * destinationAlpha * (1 - sourceAlpha * coverage)) /
+                outputAlpha,
+              );
+            }
+            next[offset + 3] = Math.round(outputAlpha * 255);
+          }
+        }
+        if (
+          before[0] !== next[offset] ||
+          before[1] !== next[offset + 1] ||
+          before[2] !== next[offset + 2] ||
+          before[3] !== next[offset + 3]
+        ) {
+          changedBounds = include(changedBounds, x, y);
+        }
+      }
+    }
+  }
+
+  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
+}

