it('restarts sampling from source origin in unaligned mode across segments', () => {
  const dest = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 8,
    height: 8,
    pixels: new Uint8ClampedArray(8 * 8 * 4).fill(0),
  });
  // Unaligned: first dab at (2,2) samples source at (0,0)=red.
  // Second dab at (5,5) should also sample source at (0,0)=red (restart).
  const patch = cloneStampStroke(
    dest,
    sourceStore,
    { x: 0, y: 0 },
    false,
    [{ x: 2, y: 2 }, { x: 5, y: 5 }],
    baseOptions,
  );
  // Both points should receive red from source origin.
