it('supports erase mode', () => {
  const dest = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 4,
    height: 4,
    pixels: new Uint8ClampedArray([255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255, 255]),
  });
  const patch = cloneStampStroke(
    dest,
    sourceStore,
    { x: 0, y: 0 },
    true,
    [{ x: 0, y: 0 }],
    { ...baseOptions, mode: 'erase', opacity: 0.5 },
  );
  // Patch should contain changed data with reduced alpha.
  expect(patch.width).toBeGreaterThan(0);
  expect(patch.height).toBeGreaterThan(0);
  const alphaValues = Array.from(patch.pixels).filter((_, i) => i % 4 === 3);
  expect(alphaValues.length).toBeGreaterThan(0);
  expect(Math.max(...alphaValues)).toBeLessThan(255);
});

