interface CloneSourcePoint {
  readonly documentX: number;
  readonly documentY: number;
  readonly localX: number;
  readonly localY: number;
}

/**
 * Paints a clone stamp stroke by sampling pixels from a source pixel store and
 * writing them into a destination pixel layer. The source origin is in document
 * space; aligned mode preserves the source-to-destination offset throughout the
 * gesture, while unaligned mode resets the source origin for each new stroke
 * segment.
 */
export function cloneStampStroke(
  destinationLayer: PixelLayer,
  sourcePixelStore: TiledPixelStore,
  /** Document-space source origin established by Alt/Option-click. */
  sourceOrigin: { readonly x: number; readonly y: number },
  /** True to keep the source offset constant across stroke segments. */
  aligned: boolean,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  /** World transform for the destination layer. Defaults to layer.transform. */
  worldTransform: LayerTransform = destinationLayer.transform,
): PixelPatch {
  validateLayer(destinationLayer);
  validateTransform(worldTransform);
  validateSelection(selection);
  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
  assertFinite(options.size, 'Clone stamp size');
  if (options.size <= 0) throw new RangeError('Clone stamp size must be greater than 0');
  assertUnit(options.hardness, 'Clone stamp hardness');
  assertUnit(options.opacity, 'Clone stamp opacity');
  const mode: unknown = options.mode;
  if (mode !== 'source-over' && mode !== 'erase') {
    throw new RangeError('Clone stamp mode must be source-over or erase');
  }
  for (const [index, point] of points.entries()) {
    assertFinite(point.x, `Clone stamp point ${String(index)} x`);
    assertFinite(point.y, `Clone stamp point ${String(index)} y`);
    assertUnit(point.pressure ?? 1, `Clone stamp point ${String(index)} pressure`);
  }

  const radius = options.size / 2;

