it('preserves the source-to-destination offset in aligned mode', () => {
  const dest = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 8,
    height: 8,
    pixels: new Uint8ClampedArray(8 * 8 * 4).fill(0),
  });
  // Source origin at (1,1), painting at (4,4) should sample source at (4,4).
  const patch = cloneStampStroke(
    dest,
    sourceStore,
    { x: 1, y: 1 },
    true,
    [{ x: 4, y: 4 }],
    baseOptions,
  );
  // The source only has data in the 0..3 range; sampling at (4,4) clamps to (3,3).
  // But with the offset, (4,4) - (1,1) = (3,3) in source coords.
  const result = dest.pixelStore.read({ x: 4, y: 4, width: 1, height: 1 });
  expect(result[3]).toBe(255); // alpha should be non-zero if any paint occurred
});

