it('handles missing source state by writing zeros (no crash)', () => {
  const emptySource = TiledPixelStore.empty(4, 4);
  const dest = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 4,
    height: 4,
    pixels: new Uint8ClampedArray([100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255]),
  });
  // Painting without source should not corrupt existing pixels.
  const patch = cloneStampStroke(
    dest,
    emptySource,
    { x: 0, y: 0 },
    true,
    [{ x: 0, y: 0 }],
    { ...baseOptions, mode: 'source-over' },
  );
  // Result should be transparent (alpha 0) since source is empty.
  const hasAlpha = Array.from(patch.pixels).some((v, i) => i % 4 === 3 && v > 0);
  // Patch may be empty if no changes were made.
  if (!hasAlpha) {
    expect(patch.width).toBe(0);
  }
});

