it('handles missing source state by writing zeros (no crash)', () => {
  const emptySource = TiledPixelStore.empty(4, 4);
  const dest = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 4,
    height: 4,
    pixels: new Uint8ClampedArray([100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255, 100, 100, 100, 255]),
  });
  const before = new Uint8ClampedArray(dest.pixelStore.toContiguous());
  // Painting without source should not corrupt existing pixels.
  const patch = cloneStampStroke(
    dest,
    emptySource,
    { x: 0, y: 0 },
    true,
    [{ x: 0, y: 0 }],
    { ...baseOptions, mode: 'source-over' },
  );
  // Result should be all zeros (transparent) since source is empty.
  expect(dest.pixelStore.read({ x: 0, y: 0, width: 1, height: 1 })[3]).toBe(0);
  // But other pixels should remain unchanged.
  expect(dest.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 })).toEqual(before.subarray(12 * 4, 16 * 4));
});

